		long cacheBytes = cacheEnvelopeBytes(cacheCapacity, MAX_CACHEABLE_KEY_BYTES);
		return saturatedAdd(512L,
				saturatedAdd(ADAPTIVE_FIXED_SCRATCH_BYTES,
						saturatedAdd(inputBytes, saturatedAdd(outputBytes, cacheBytes))));
